mapper.select:
SELECT id, user_id, biz_type, biz_id, points, remark, create_time
FROM user_point_ledger
WHERE user_id = #{userId}
ORDER BY create_time DESC, id DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM user_point_ledger
WHERE user_id = #{userId}
  AND biz_type = #{bizType}
  AND create_time >= #{from}

SELECT COALESCE(SUM(points), 0)
FROM user_point_ledger
WHERE user_id = #{userId}
  AND create_time >= #{from}
  AND points > 0
